output.arguments:
{"command":"cat > /tmp/q.sql <<'SQL'
WITH ops AS (SELECT o.operation_id,o.route_id,o.opened_at_ms, CASE WHEN o.opened_at_ms<1777723200000 THEN 'reference' ELSE 'incident' END period,a.pool_id,pp.deadline_ms FROM logical_operations o JOIN service_routes r ON r.route_id=o.route_id JOIN services s ON s.service_id=r.service_id JOIN route_assignments a ON a.route_id=o.route_id AND o.opened_at_ms>=a.effective_from_ms AND o.opened_at_ms<a.effective_to_ms JOIN policy_profiles pp ON pp.profile_id=a.profile_id WHERE s.service_code='parcel-index' AND o.opened_at_ms>=1777716000000 AND o.opened_at_ms<1777723200000), po AS (SELECT ops.*,count(attempt_id) attempts,sum(CASE WHEN f.is_success=0 THEN 1 ELSE 0 END) failed_attempts,max(attempt_no) maxno,max(CASE WHEN attempt_no=(select max(attempt_no) from attempt_events x where x.operation_id=ops.operation_id) THEN f.is_success END) final_success FROM ops LEFT JOIN attempt_events USING(operation_id) LEFT JOIN failure_codes f USING(code_id) GROUP BY ops.operation_id) SELECT period,pool_code,count(*) operations,sum(final_success=0) terminal_failures,100.0*sum(final_success=0)/count(*) terminal_pct,sum(attempts) attempts,sum(failed_attempts) failed_attempts,100.0*sum(failed_attempts)/sum(attempts) attempt_pct,sum(maxno>1) retried,min(deadline_ms),max(deadline_ms) FROM po JOIN worker_pools USING(pool_id) GROUP BY period,pool_id;
SQL
sqlite3 -header -column ../data/current.db < /tmp/q.sql"}

arguments.command:
sed 's/CASE WHEN o.opened_at_ms<1777723200000/CASE WHEN o.opened_at_ms<1777719600000/' /tmp/q.sql >/tmp/q2; sqlite3 -header -column ../data/current.db </tmp/q2; sqlite3 -header -column ../data/current.db <<'SQL'
select p.pool_code,t.signal_code,s.unit,avg(t.value) mean_value,case when t.measured_at_ms<1777719600000 then 'reference' else 'incident' end period from telemetry_samples t join worker_pools p using(pool_id) join telemetry_signals s using(signal_id) where t.measured_at_ms>=1777716000000 and t.measured_at_ms<1777723200000 and p.pool_code in ('idx-north','idx-south') group by p.pool_id,s.signal_id,period order by period,p.pool_code,s.signal_code;
SQL

